/* Channel changes do not reload the campus or create community visits. */
function createChannels110(multiplayer){
 const settings=document.getElementById('settings'),row=document.createElement('section');row.className='channel110Setting';row.innerHTML='<div><strong>접속 채널</strong><small data-current>연결 확인 중</small></div><button type="button" data-open>채널 변경</button>';
 const anchor=document.getElementById('returnTitle');(anchor?.parentElement||settings).insertBefore(row,anchor||null);
 const d=document.createElement('dialog');d.id='channels110';d.setAttribute('aria-labelledby','channels110Title');d.innerHTML='<header><div><small>같은 캠퍼스, 함께 탐방</small><h2 id="channels110Title">채널 선택</h2></div><button data-close aria-label="채널 선택 닫기">×</button></header><p>친구와 같은 번호를 선택하세요. 가까운 사람부터 보여요.</p><div class="channel110List"></div><p data-status role="status" aria-live="polite"></p>';document.body.append(d);
 const list=d.querySelector('.channel110List'),status=d.querySelector('[data-status]'),current=row.querySelector('[data-current]');let last='',message='';
 const reasons={busy:'앉아 있거나 버스를 이용 중이에요. 일어나거나 하차·대기를 취소한 뒤 변경해 주세요.',full:'선택한 채널이 가득 찼어요. 기존 채널을 유지합니다.',connection:'연결을 확인해 주세요. 다른 채널로 자동 이동하지 않아요.',timeout:'응답이 늦어 재접속으로 실제 채널을 확인하고 있어요.',invalid:'선택한 채널을 확인해 주세요.',closed:'채널 변경을 종료했어요.'};
 function render(){const s=multiplayer.channelState(),single=s.channels.length<=1,capacity=s.channels.find(c=>c.id===s.channel)?.capacity||300;row.querySelector('strong').textContent=single?'함께 탐방':'접속 채널';row.querySelector('[data-open]').hidden=single&&s.connected;row.querySelector('[data-open]').textContent=single?'다시 연결':'채널 변경';current.textContent=single?(s.connected?s.population+' / '+capacity+'명 · 가까운 사람부터 보여요':'공용 캠퍼스 연결 대기'):(s.channel?'채널 '+s.channel:'자동 배정')+' · '+(s.connected?s.population+' / '+capacity+'명':'연결 대기');const signature=JSON.stringify(s);if(signature!==last){last=signature;list.replaceChildren();for(const id of s.channels.map(c=>c.id)){const c=s.channels.find(c=>c.id===id),selected=s.connected&&s.channel===id,full=c&&c.population>=c.capacity,b=document.createElement('button');b.type='button';b.className='channel110Option'+(selected?' selected':'');b.setAttribute('aria-pressed',String(selected));b.disabled=s.switching||selected||!!full||!c;const name=document.createElement('strong'),detail=document.createElement('span');name.textContent='채널 '+id+(selected?' ✓':'');detail.textContent=c?c.population+' / '+c.capacity+'명 · '+(full?'가득 참':c.population>=80?'혼잡':c.population>=50?'보통':'여유'):'확인 중';b.append(name,detail);b.onclick=async()=>{message='채널을 확인하고 있어요…';status.textContent=message;const result=await multiplayer.switchChannel(id);message=result.ok?(result.connecting?'선택한 채널에 연결 중이에요.':'채널 '+result.channel+'로 이동했어요.'):(reasons[result.reason]||'변경하지 못했어요. 다시 시도해 주세요.');status.textContent=message;render()};list.append(b)}}status.textContent=message;}
 row.querySelector('[data-open]').onclick=()=>{if(multiplayer.channelState().channels.length<=1){multiplayer.switchChannel('01');return}message='';multiplayer.requestChannels();render();d.showModal()};d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>row.querySelector('[data-open]').focus());
 d.addEventListener('keydown',e=>{e.stopPropagation();if(e.code==='KeyP')d.close()});window.addEventListener('campus-channel110',render);let poll=0;setInterval(()=>{if(settings.open||d.open){render();if(Date.now()-poll>2000){poll=Date.now();multiplayer.requestChannels()}}},1000);render();
}
